BEGIN
    SET XACT_ABORT ON;

    BEGIN TRY

	BEGIN TRANSACTION; 

		UPDATE sync SET sync.TX2ProductComboId = p.ProductComboId FROM TXCProductComboSync sync INNER JOIN dbo.Product p with(nolock) ON sync.TX2ProductId = p.Id WHERE sync.RunId = @RunId;

		UPDATE sync SET sync.TX2ProductComboSetId = pcs.id  FROM TXCProductComboSync sync INNER JOIN ProductComboSet pcs with(nolock) ON pcs.ProductComboId = sync.TX2ProductComboId AND pcs.ChildProductId = sync.TX2ChildProductId AND pcs.ChildProductVersionId = sync.TX2ChildProductVersionId WHERE sync.RunId = @RunId;

		UPDATE pcs SET pcs.[Sequence] = sync.TXCSequence, pcs.[Status] = sync.TXCStatus FROM dbo.ProductComboSet pcs INNER JOIN TXCProductComboSync sync with(nolock) ON pcs.id = sync.TX2ProductComboSetId WHERE sync.RunId = @RunId AND sync.TX2ProductComboSetId IS NOT NULL;

		INSERT INTO dbo.ProductComboSet(ProductComboId,ChildProductId,ChildProductVersionId,[Sequence],Status) SELECT sync.TX2ProductComboId, sync.TX2ChildProductId, sync.TX2ChildProductVersionId,sync.TXCSequence,sync.TXCStatus from TXCProductComboSync sync with(nolock) WHERE sync.RunId = @RunId AND sync.TX2ProductComboId is NOT NULL AND sync.TX2ProductComboSetId IS NULL;

        Create table #tempc
        (
            TX2ProductId int,
            TX2ProductComboId int
        );

        INSERT INTO #tempc select distinct sync.TX2ProductId,NULL FROM TXCProductComboSync sync INNER JOIN dbo.Product p with(nolock) ON sync.TX2ProductId = p.Id WHERE sync.RunId = @RunId and p.ProductComboId is NULL AND sync.TX2ProductComboId is NULL AND sync.TX2ProductComboSetId IS NULL;

        IF EXISTS(SELECT 1 FROM #tempc)
        BEGIN
            DECLARE @TX2ProductId int

            DECLARE cursor_pc CURSOR for SELECT TX2ProductId FROM #tempc
            OPEN cursor_pc
            FETCH NEXT FROM cursor_pc
            INTO @TX2ProductId

            WHILE @@FETCH_STATUS = 0
            BEGIN
                INSERT INTO dbo.ProductCombo DEFAULT VALUES;
                UPDATE #tempc SET TX2ProductComboId = SCOPE_IDENTITY() WHERE TX2ProductId = @TX2ProductId;
                FETCH NEXT FROM cursor_pc
                INTO @TX2ProductId
            END

            CLOSE cursor_pc
            DEALLOCATE cursor_pc

            INSERT INTO dbo.ProductComboSet(ProductComboId,ChildProductId,ChildProductVersionId,[Sequence],Status) SELECT t.TX2ProductComboId,sync.TX2ChildProductId, sync.TX2ChildProductVersionId,sync.TXCSequence,sync.TXCStatus from TXCProductComboSync sync with(nolock) INNER JOIN #tempc t On sync.TX2ProductId = t.TX2ProductId WHERE sync.RunId = @RunId AND sync.TX2ProductComboId is NULL AND sync.TX2ProductComboSetId IS NULL;

            UPDATE p SET p.ProductComboId = t.TX2ProductComboId  from dbo.Product p INNER JOIN #tempc t On p.id = t.TX2ProductId;

            UPDATE pv SET pv.ProductComboId = t.TX2ProductComboId from dbo.ProductVersion pv INNER JOIN #tempc t On pv.ProductId = t.TX2ProductId and pv.IsCurrentVersion = 1;

        END
        
        drop table #tempc;
        
	COMMIT TRANSACTION;
				 			 
    END TRY
    BEGIN CATCH 
       IF @@TRANCOUNT > 0
       BEGIN
          ROLLBACK TRANSACTION
       END;

	   THROW 99999, 'Fail to update product combo', 1
    END CATCH;
    SET XACT_ABORT OFF;
END

